<?php ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PRIMONIZER FOREX AI</title><style>
*{box-sizing:border-box}body{margin:0;background:#050a10;color:#eef6ff;font:15px Arial,sans-serif}.wrap{max-width:1450px;margin:auto;padding:16px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px}.brand{font-size:23px;font-weight:900}.brand b{color:#27e0a0}.badge{border:1px solid #29435b;padding:8px 12px;border-radius:20px;color:#9fb4c7}.card{background:#0b1622;border:1px solid #21384e;border-radius:14px;padding:16px;margin-top:14px}.hero,.uploadGrid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.muted{color:#91a7bb;line-height:1.5}.slot{border:1px dashed #34536d;border-radius:12px;padding:12px;background:#07111b}.slot input,.slot select{width:100%;margin-top:8px;background:#050d15;color:#fff;border:1px solid #29435b;padding:10px;border-radius:8px}.thumb{display:none;width:100%;height:150px;object-fit:contain;margin-top:8px;background:#02060a;cursor:zoom-in}.btn{width:100%;padding:15px;margin-top:14px;border:0;border-radius:10px;background:#27e0a0;color:#03120d;font-weight:900;cursor:pointer}.btn:disabled{opacity:.5}.result{display:none}.charts{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.chartCard{background:#02070d;border:1px solid #29435b;border-radius:12px;overflow:hidden}.chartHead{padding:12px;background:#091521;display:flex;justify-content:space-between;gap:10px}.chartWrap{position:relative;background:#02060a;overflow:hidden}.chartImg{width:100%;display:block;cursor:zoom-in}.story{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.storyStep{border:1px solid #29435b;border-radius:10px;padding:12px;background:#07111b;min-height:100px}.storyStep b{display:block;margin-bottom:7px;color:#27e0a0}.info{padding:12px;background:#091521}.panel{border:1px solid #29435b;border-radius:10px;padding:11px;margin-top:9px}.ob{border-left:4px solid #27e0a0;padding:10px;background:#061a14}.entry{border-left:4px solid #ffd166;padding:10px;background:#1d1805;margin-top:8px}.confirm{border-left:4px solid #55a9ff;padding:10px;background:#061525;margin-top:8px}.danger{border-left:4px solid #ff6378;padding:10px;background:#1d080d;margin-top:8px}.target{border-left:4px solid #ffd166;padding:10px;background:#1d1805;margin-top:8px}.concept{border-left:4px solid #b47cff;padding:10px;background:#140d22;margin-top:8px}.final{font-size:19px;font-weight:900;white-space:pre-line;line-height:1.55}.error{color:#ff6378;margin-top:10px}.legend{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}.legend span{padding:5px 8px;border-radius:7px;background:#101e2b;border:1px solid #29435b;font-size:12px}.modal{display:none;position:fixed;z-index:99;inset:0;background:#000e;align-items:center;justify-content:center;padding:15px}.modal.open{display:flex}.modal img{max-width:96vw;max-height:92vh}.close{position:fixed;right:20px;top:10px;font-size:35px;cursor:pointer}.tutorialBox{margin-top:10px;border:1px solid #29435b;padding:12px;border-radius:10px;background:#07111b}.tutorialTitle{color:#27e0a0;font-weight:900}.verticalNote{font-size:11px;color:#7890a4;margin-top:6px}.currentBox{border-left:4px solid #fff;padding:10px;background:#101820;margin-top:8px}.scenarioBox{border-left:4px solid #ffd166;padding:10px;background:#1d1805;margin-top:8px}@media(max-width:900px){.hero,.uploadGrid,.charts,.story{grid-template-columns:1fr}.wrap{padding:9px}.top{align-items:flex-start;flex-direction:column}}
</style></head><body><div class="wrap"><div class="top"><div class="brand">PRIMONIZER <b>FOREX AI</b></div><div class="badge">● DEEP MULTI-TIMEFRAME VISUAL TUTOR</div></div><div class="hero"><div class="card"><h1>Upload 1–4 timeframes</h1><p class="muted">Use the SAME pair at different timeframes. Higher timeframes build context; the lowest relevant timeframe refines the current-price decision.</p><form id="form"><label>SYMBOL</label><select name="symbol" style="width:100%;background:#050d15;color:white;padding:11px;border:1px solid #29435b;border-radius:8px"><option>XAUUSD</option><option>EURUSD</option><option>GBPUSD</option><option>USDJPY</option><option>BTCUSD</option><option>V75</option><option>OTHER</option></select><div class="uploadGrid" id="slots"></div><button class="btn" id="go">ANALYZE ALL TIMEFRAMES</button><div id="err" class="error"></div></form></div><div class="card"><h2>Visual decision map</h2><div class="final">STRUCTURE
LIQUIDITY
DISPLACEMENT
BOS / CHoCH
VALID OB / FVG
CURRENT PRICE
ENTRY
CONFIRMATION
INVALIDATION / SL
TP1
TP2</div><div class="legend"><span>🟢 Bullish / Entry</span><span>🔴 Bearish / Invalidation</span><span>🟡 Liquidity / Targets</span><span>🔵 FVG / Confirmation</span><span>⚪ Structure</span><span>🟣 Concept explanation</span></div></div></div><section id="result" class="result"><div class="card"><h2 id="title"></h2><div id="final" class="final"></div><div id="current" class="currentBox"></div><div id="reason" class="muted"></div><div id="confluence" class="muted"></div></div><div id="charts" class="charts"></div><div class="card"><h2>Visual Market Story</h2><div id="story" class="story"></div></div></section></div><div id="modal" class="modal"><span class="close" id="close">×</span><img id="big"></div><script>
const slots=document.getElementById('slots');for(let i=0;i<4;i++){const s=document.createElement('div');s.className='slot';s.innerHTML='<b>CHART '+(i+1)+'</b><select class="tf"><option>H4</option><option>H1</option><option>M30</option><option>M15</option><option>M5</option><option>M1</option><option>D1</option><option>UNKNOWN</option></select><input class="file" type="file" accept="image/png,image/jpeg,image/webp"><img class="thumb"><small class="size" style="display:block;color:#71869a;margin-top:6px"></small>';slots.appendChild(s);const f=s.querySelector('.file'),im=s.querySelector('.thumb'),sz=s.querySelector('.size');f.addEventListener('change',()=>{if(f.files&&f.files[0]){im.src=URL.createObjectURL(f.files[0]);im.style.display='block';sz.textContent='Selected: '+(f.files[0].size/1048576).toFixed(2)+' MB'}})}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function openBig(src){document.getElementById('big').src=src;document.getElementById('modal').classList.add('open')}document.getElementById('close').onclick=()=>document.getElementById('modal').classList.remove('open');document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')e.currentTarget.classList.remove('open')};
function compress(file){return new Promise((resolve,reject)=>{const im=new Image(),u=URL.createObjectURL(file);im.onload=()=>{let w=im.naturalWidth,h=im.naturalHeight,m=Math.max(w,h);if(m>1600){w=Math.round(w*1600/m);h=Math.round(h*1600/m)}const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);c.toBlob(b=>{URL.revokeObjectURL(u);if(!b)return reject(new Error('Could not prepare image'));resolve(new File([b],'chart.jpg',{type:'image/jpeg'}))},'image/jpeg',.78)};im.onerror=()=>reject(new Error('Could not read image'));im.src=u})}
function colorFor(type){if(!type)return '#fff';if(['OB_BULL','ENTRY','TARGET1','TARGET2','HL'].includes(type))return '#27e0a0';if(['OB_BEAR','INVALIDATION','LH'].includes(type))return '#ff6378';if(['FVG','CONFIRMATION','BOS','CHoCH','DISPLACEMENT'].includes(type))return '#55a9ff';if(['LIQUIDITY','SWEEP','TARGET'].includes(type))return '#ffd166';return '#fff'}
function drawVerticalLabel(ctx,text,x,y,c,w,h){const words=String(text||'').replace(/[_-]+/g,' ').split(/\s+/).filter(Boolean);ctx.fillStyle=c;ctx.textAlign='left';ctx.textBaseline='middle';const lh=Math.max(14,w/65);let yy=Math.max(lh,y);for(const word of words){ctx.fillText(word,Math.min(w-150,Math.max(5,x)),Math.min(h-lh,yy));yy+=lh;if(yy>h-lh)break}}
function arrow(ctx,x1,y1,x2,y2,c){ctx.strokeStyle=c;ctx.fillStyle=c;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();const a=Math.atan2(y2-y1,x2-x1),s=12;ctx.beginPath();ctx.moveTo(x2,y2);ctx.lineTo(x2-s*Math.cos(a-.45),y2-s*Math.sin(a-.45));ctx.lineTo(x2-s*Math.cos(a+.45),y2-s*Math.sin(a+.45));ctx.closePath();ctx.fill()}
function annotate(src,a){return new Promise(resolve=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas'),w=Math.min(1600,im.naturalWidth),h=Math.round(im.naturalHeight*(w/im.naturalWidth));c.width=w;c.height=h;const x=c.getContext('2d');x.drawImage(im,0,0,w,h);x.font='bold '+Math.max(12,w/78)+'px Arial';const anns=a.annotations||[];anns.forEach(o=>{const X=(+o.x||0)*w,Y=(+o.y||0)*h,C=colorFor(o.type);x.strokeStyle=C;x.fillStyle=C;x.lineWidth=3;if(o.x2!=null&&o.y2!=null){const X2=(+o.x2||0)*w,Y2=(+o.y2||0)*h,left=Math.min(X,X2),top=Math.min(Y,Y2),ww=Math.abs(X2-X),hh=Math.abs(Y2-Y);x.globalAlpha=.14;x.fillRect(left,top,ww,hh);x.globalAlpha=1;x.strokeRect(left,top,ww,hh);drawVerticalLabel(x,o.label||o.type,left+6,top+14,C,w,h)}else{x.beginPath();x.arc(X,Y,7,0,Math.PI*2);x.fill();drawVerticalLabel(x,o.label||o.type,X+10,Y-10,C,w,h)}});const p=a.path||[];for(let i=1;i<p.length;i++){const q1=p[i-1],q2=p[i],c=q2.direction==='DOWN'?'#ff6378':q2.direction==='UP'?'#27e0a0':'#ffd166';arrow(x,q1.x*w,q1.y*h,q2.x*w,q2.y*h,c);drawVerticalLabel(x,q2.label,q2.x*w+8,q2.y*h-8,c,w,h)}resolve(c.toDataURL('image/jpeg',.9))};im.src=src})}
function tutorialHtml(q){const t=q.tutorial||[],cs=q.concepts||[];let h='';if(cs.length)h+='<div class="tutorialBox"><div class="tutorialTitle">CONCEPTS — WHAT + WHY</div>'+cs.map(z=>'<div class="concept"><b>'+esc(z.name)+'</b><br><b>WHAT:</b> '+esc(z.what)+'<br><b>WHY:</b> '+esc(z.why)+'</div>').join('')+'</div>';if(t.length)h+='<div class="tutorialBox"><div class="tutorialTitle">STEP-BY-STEP EXPLANATION</div>'+t.map((z,i)=>'<div class="panel"><b>'+((i+1))+'. '+esc(z.title)+'</b><br>'+esc(z.text)+'</div>').join('')+'</div>';return h}
async function render(d,compressed){document.getElementById('result').style.display='block';const o=d.analysis?.overall||{};document.getElementById('title').textContent=(o.trade_state||'WAIT')+' • '+(o.direction||'NEUTRAL')+' • '+(o.next_move||'WAIT');document.getElementById('final').textContent='ENTRY\n'+(o.entry_plan||'WAIT FOR CONFIRMATION')+'\n\nCONFIRMATION\n'+(o.confirmation||'Not defined')+'\n\nINVALIDATION / SL\n'+(o.invalidation||'Not defined')+'\n\nTP1\n'+(o.targets?.tp1||'Not defined')+'\n\nTP2\n'+(o.targets?.tp2||'Not defined');document.getElementById('current').innerHTML='<b>CURRENT PRICE</b><br>'+esc(o.current_price_context||'The current rightmost price state was not clearly readable.')+'<div class="scenarioBox"><b>WHY THIS DECISION</b><br>'+esc(o.reason||'Not defined')+'</div>';document.getElementById('reason').textContent=o.risk_note||'';document.getElementById('confluence').innerHTML='<b>CONFLUENCE:</b> '+esc((d.analysis?.confluence||[]).join(' • '));document.getElementById('story').innerHTML=(o.market_story||[]).map((x,i)=>'<div class="storyStep"><b>STEP '+(i+1)+'</b>'+esc(x)+'</div>').join('');const out=document.getElementById('charts');out.innerHTML='';for(let i=0;i<compressed.length;i++){const src=URL.createObjectURL(compressed[i]),q=(d.analysis.charts||[]).find(z=>Number(z.index)===i+1)||(d.analysis.charts||[])[i]||{},img=await annotate(src,q),card=document.createElement('div');card.className='chartCard';card.innerHTML='<div class="chartHead"><b>'+esc(q.timeframe||'CHART '+(i+1))+'</b><span>'+esc(q.role||'')+'<br>'+esc(q.direction||'NEUTRAL')+' • '+esc(q.next_move||'WAIT')+'</span></div>';const wrap=document.createElement('div');wrap.className='chartWrap';const pic=document.createElement('img');pic.className='chartImg';pic.src=img;pic.onclick=()=>openBig(img);wrap.appendChild(pic);card.appendChild(wrap);const ob=q.valid_order_block||{},en=q.entry||{};const inf=document.createElement('div');inf.className='info';inf.innerHTML='<div class="currentBox"><b>● CURRENT PRICE STATE</b><br>'+esc(q.current_state||'Not clearly readable')+'<br><small>'+esc(q.current_price_note||'')+'</small></div><div class="ob"><b>🟢 VALID ORDER BLOCK: '+esc(ob.status||'NONE')+'</b><br>'+esc(ob.why||'No reliable candidate.')+'<br><small>Why nearby alternatives are not selected: '+esc(ob.why_not_others||'Insufficient evidence')+'</small></div><div class="entry"><b>🟡 ENTRY / WATCH ZONE</b><br>'+esc(en.zone||'Not clearly visible')+'<br><small>State: '+esc(en.state||'NONE')+'</small></div><div class="confirm"><b>🔵 CONFIRMATION</b><br>'+esc(en.confirmation||'Wait for confirmation before entry.')+'</div><div class="danger"><b>🔴 INVALIDATION / STOP CONDITION</b><br>'+esc(en.invalidation||'Not defined')+'</div><div class="target"><b>🎯 FORWARD TARGET</b><br>'+esc(en.target||'Not defined')+'</div>'+tutorialHtml(q);card.appendChild(inf);out.appendChild(card)}}
document.getElementById('form').onsubmit=async e=>{e.preventDefault();const err=document.getElementById('err'),btn=document.getElementById('go'),ins=[...document.querySelectorAll('.file')],ts=[...document.querySelectorAll('.tf')],fd=new FormData(),compressed=[];err.textContent='';try{for(let i=0;i<ins.length;i++){if(ins[i].files[0]){btn.textContent='PREPARING '+(compressed.length+1)+'/'+ins.filter(x=>x.files[0]).length+'...';const f=await compress(ins[i].files[0]);compressed.push(f);fd.append('charts[]',f);fd.append('timeframes[]',ts[i].value)}}if(!compressed.length){err.textContent='Choose at least one image first.';return}fd.append('symbol',document.querySelector('[name=symbol]').value);btn.disabled=true;btn.textContent='DEEP MULTI-TIMEFRAME ANALYSIS...';const r=await fetch('analyze.php',{method:'POST',body:fd});const text=await r.text();let d;try{d=JSON.parse(text)}catch(e){throw new Error('Server returned non-JSON. '+text.slice(0,700))}if(!r.ok||d.error)throw new Error(d.error||'Analysis failed');await render(d,compressed);document.getElementById('result').scrollIntoView({behavior:'smooth'})}catch(e){err.textContent=e.message}finally{btn.disabled=false;btn.textContent='ANALYZE ALL TIMEFRAMES'}};</script></body></html>